// Get the incoming data from the Webhook node
const body = $input.first().json.body;

const errors = [];

// Check each required top-level field
const requiredFields = ['request_id', 'marketplace_id', 'seller_id', 'variation_structure'];
for (const field of requiredFields) {
  if (!body[field]) {
    errors.push({ field: field, reason: 'MISSING_REQUIRED_FIELD' });
  }
}

// variation_structure must be one of 3 exact values
const validStructures = ['single_theme', 'double_theme', 'not_sure'];
if (body.variation_structure && !validStructures.includes(body.variation_structure)) {
  errors.push({ field: 'variation_structure', reason: 'INVALID_VALUE' });
}

// auto_execute must be false
if (body.auto_execute === true) {
  errors.push({ field: 'auto_execute', reason: 'AUTO_EXECUTE_NOT_ALLOWED' });
}

// items must be an array with 2 to 10 entries
if (!Array.isArray(body.items)) {
  errors.push({ field: 'items', reason: 'MISSING_REQUIRED_FIELD' });
} else {
  if (body.items.length < 2) {
    errors.push({ field: 'items', reason: 'MINIMUM_ITEMS_REQUIRED' });
  }
  if (body.items.length > 10) {
    errors.push({ field: 'items', reason: 'MAXIMUM_ITEMS_EXCEEDED' });
  }
  body.items.forEach((item, index) => {
    ['asin', 'sku', 'brand'].forEach((key) => {
      if (!item[key]) {
        errors.push({ field: `items[${index}].${key}`, reason: 'MISSING_REQUIRED_FIELD' });
      }
    });
  });
}

// Build the final decision
if (errors.length > 0) {
  return [{
    json: {
      request_id: body.request_id || null,
      decision: 'BLOCKED',
      errors: errors,
      message: 'One or more required fields are missing or invalid.'
    }
  }];
}

return [{
  json: {
    request_id: body.request_id,
    decision: 'VALID_INPUT',
    message: 'Input passed all required field checks.',
    data: body
  }
}];

const supabaseResult = $input.first().json;
const originalData = $('Input Validator').first().json;
return [{ json: { ...originalData, supabase_log: { status: 'ok', inserted_id: supabaseResult[0]?.id || supabaseResult?.id } } }];

const original = $('Restore After Supabase').first().json;
const ptdRaw = $('Fetch PTD Schema').first().json;

const ptdData = ptdRaw.error || ptdRaw.status === 403
  ? { supported_variation_themes: ['ColorSize', 'Color', 'Size'] }
  : ptdRaw;

if (original.decision === 'BLOCKED' || original.decision === 'DUPLICATE_REQUEST') {
  return [{ json: original }];
}

const splitItems = $('Split Items For Real Fetch').all().map(function(i) { return i.json; });
const catalogResults = $('Fetch Real Catalog Data').all().map(function(i) { return i.json; });
const listingResults = $('Fetch Real Listing Data').all().map(function(i) { return i.json; });

const enrichedItems = splitItems.map(function(splitItem, idx) {
  const catalogData = catalogResults[idx] || {};
  const listingData = listingResults[idx] || {};
  const brand = catalogData.brand || splitItem.brand;
  const normalized_brand = (catalogData.normalized_brand || brand || '').toLowerCase().trim();

  return {
    asin: splitItem.asin,
    sku: splitItem.sku,
    brand: brand,
    normalized_brand: normalized_brand,
    product_type: catalogData.product_type || 'CLOTHING',
    category: catalogData.category || 'Shirts',
    parent_sku: null,
    parentage: splitItem.parentage || null,
    variation_values: splitItem.variation_values || null,
    matrix_assignments: splitItem.matrix_assignments || null,
    variation_value: splitItem.variation_value || null,
    supported_variation_themes: ptdData.supported_variation_themes || [],
    listing_attributes: listingData
  };
});

// Genuine cross-item brand check — each item's OWN real fetched brand, not one shared value
const allBrands = enrichedItems.map(function(it) { return it.normalized_brand; });
const brandsMatch = allBrands.every(function(b) { return b === allBrands[0]; });

if (!brandsMatch) {
  const brandsFound = enrichedItems.map(function(it) { return it.brand; });
  return [{ json: {
    request_id: original.data.request_id,
    decision: 'BLOCKED',
    reason: 'BRAND_MISMATCH',
    message: 'All items must belong to the same brand. Found: ' + brandsFound.join(', '),
    variation_structure: original.data.variation_structure,
    items: enrichedItems
  }}];
}

// Genuine cross-item product type check — now possible since each item has its own real fetch
const allProductTypes = enrichedItems.map(function(it) { return it.product_type; });
const productTypesMatch = allProductTypes.every(function(pt) { return pt === allProductTypes[0]; });

if (!productTypesMatch) {
  return [{ json: {
    request_id: original.data.request_id,
    decision: 'BLOCKED',
    reason: 'PRODUCT_TYPE_MISMATCH',
    message: 'All items must be the same product type. Found: ' + allProductTypes.join(', '),
    variation_structure: original.data.variation_structure,
    items: enrichedItems
  }}];
}

return [{ json: {
  request_id: original.data.request_id,
  decision: 'CAN_CONTINUE_TO_DRY_RUN',
  message: 'Brand and product type checks passed via real per-item proxy data.',
  request_text: original.data.request_text,
  variation_structure: original.data.variation_structure,
  sizes: original.data.sizes || null,
  colors: original.data.colors || null,
  matrix_assignments: original.data.matrix_assignments || null,
  simulate_missing_value: original.data.simulate_missing_value || false,
  items: enrichedItems
}}];

const prev = $('Assemble Proxy Data').first().json;

if (prev.decision === 'BLOCKED' || prev.decision === 'DUPLICATE_REQUEST') {
  return [{ json: prev }];
}

const normalizedItems = prev.items.map(function(item) {
  return {
    asin: (item.asin || '').trim(),
    sku: (item.sku || '').trim(),
    brand: (item.brand || '').trim(),
    normalized_brand: (item.normalized_brand || item.brand || '').toLowerCase().trim(),
    product_type: (item.product_type || 'CLOTHING').toUpperCase().trim(),
    normalized_product_type: (item.product_type || 'CLOTHING').toUpperCase().trim(),
    category: (item.category || '').trim(),
    normalized_category: (item.category || '').toLowerCase().trim(),
    parent_sku: item.parent_sku || null,
    parentage: item.parentage || null,
    variation_value: item.variation_value || null,
    variation_values: item.variation_values || null,
    matrix_assignments: item.matrix_assignments || null,
    color_name: item.color_name || null,
    size_name: item.size_name || null,
    variation_theme: item.variation_theme || null,
    supported_variation_themes: item.supported_variation_themes || [],
    listing_issues: item.listing_issues || [],
    theme_attribute_status: 'unverified',
    data_source: 'mock'
  };
});

return [{ json: {
  request_id: prev.request_id,
  decision: prev.decision,
  message: prev.message,
  request_text: prev.request_text || null,
  variation_structure: prev.variation_structure,
  sizes: prev.sizes || null,
  colors: prev.colors || null,
  matrix_assignments: prev.matrix_assignments || null,
  simulate_missing_value: prev.simulate_missing_value || false,
  items: normalizedItems,
  normalized: true,
  data_source: 'mock'
}}];

const prev = $('Normalize Amazon Data').first().json;

if (prev.decision === 'BLOCKED' || prev.decision === 'DUPLICATE_REQUEST') {
  return [{ json: prev }];
}

const variationStructure = prev.variation_structure;
const supportedThemes = prev.items[0].supported_variation_themes || [];
const warnings = [];

const themeMap = {
  single_theme: ['Color', 'Size', 'Flavor', 'Scent', 'Material'],
  double_theme: ['ColorSize', 'SizeColor', 'ColorFlavor', 'SizeFlavor']
};

if (variationStructure === 'not_sure') {
  return [{ json: {
    ...prev,
    ptd_validation: {
      status: 'skipped',
      message: 'Theme validation skipped — variation_structure is not_sure.'
    }
  }}];
}

const allowedThemes = themeMap[variationStructure] || [];
const matchedTheme = allowedThemes.find(function(t) {
  return supportedThemes.includes(t);
});

if (!matchedTheme) {
  return [{ json: {
    request_id: prev.request_id,
    decision: 'BLOCKED',
    reason: 'UNSUPPORTED_VARIATION_THEME',
    message: 'The variation structure "' + variationStructure + '" does not match any supported Amazon theme for this product type. Supported themes: ' + supportedThemes.join(', '),
    issue_summary: 'Unsupported variation theme.',
    issues: [{
      issue_code: 'UNSUPPORTED_VARIATION_THEME',
      severity: 'hard_block',
      message: 'Theme not supported for this product type.',
      can_user_fix: false,
      can_user_override: false
    }],
    next_action: 'CANCEL_REQUEST',
    variation_structure: variationStructure,
    supported_themes: supportedThemes,
    items: prev.items
  }}];
}

const updatedItems = prev.items.map(function(item) {
  return {
    ...item,
    matched_theme: matchedTheme,
    theme_attribute_status: 'verified'
  };
});

return [{ json: {
  ...prev,
  items: updatedItems,
  ptd_validation: {
    status: 'passed',
    matched_theme: matchedTheme,
    supported_themes: supportedThemes,
    warnings: warnings
  }
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED' || previous.decision === 'DUPLICATE_REQUEST') { return [{ json: previous }]; }

const items = previous.items;
const issues = [];

const forbiddenPhrases = [
  'combine reviews', 'merge reviews', 'transfer reviews',
  'boost ranking', 'force merge', 'bypass amazon', 'manipulate reviews'
];

function scanForAbuse(value) {
  if (typeof value !== 'string') return null;
  const lower = value.toLowerCase();
  for (let i = 0; i < forbiddenPhrases.length; i++) {
    if (lower.includes(forbiddenPhrases[i])) {
      return forbiddenPhrases[i];
    }
  }
  return null;
}

let abuseFound = null;
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const fieldsToScan = ['brand', 'sku', 'asin'];
  for (let f = 0; f < fieldsToScan.length; f++) {
    const found = scanForAbuse(item[fieldsToScan[f]]);
    if (found) {
      abuseFound = found;
    }
  }
}
if (previous.request_text) {
  const found = scanForAbuse(previous.request_text);
  if (found) abuseFound = found;
}

if (abuseFound) {
  return [{
    json: {
      request_id: previous.request_id,
      decision: 'BLOCKED',
      issue_summary: 'This request was blocked for a policy violation.',
      issues: [{
        issue_code: 'REVIEW_MANIPULATION_INTENT',
        severity: 'hard_block',
        message: 'Request text contains language associated with review manipulation or policy bypass.',
        question_to_user: null,
        example_answer: null,
        can_user_fix: false,
        can_user_override: false
      }],
      next_action: 'CANCEL_REQUEST',
       variation_structure: previous.variation_structure,
       items: previous.items

    }
  }];
}

if (previous.simulate_missing_value === true) {
  issues.push({
    issue_code: 'MISSING_VARIATION_VALUE',
    severity: 'fixable',
    asin: items[0].asin,
    sku: items[0].sku,
    field: 'variation_value',
    message: items[0].sku + ' is missing its variation value.',
    question_to_user: 'Please enter the color or size for ' + items[0].sku + '.',
    example_answer: 'Red',
    can_user_fix: true,
    can_user_override: false
  });
}

if (issues.length > 0) {
  return [{
    json: {
      request_id: previous.request_id,
      decision: 'NEEDS_INPUT',
      issue_summary: issues.length + ' issue(s) need your input before continuing.',
      issues: issues,
      next_action: 'USER_CLARIFICATION_REQUIRED',
     variation_structure: previous.variation_structure,
      sizes: previous.sizes,
      colors: previous.colors,
       matrix_assignments: previous.matrix_assignments || null,

      items: previous.items
    }
  }];
}

return [{
  json: {
    request_id: previous.request_id,
    decision: 'CAN_CONTINUE_TO_DRY_RUN',
    issue_summary: 'No issues found.',
    issues: [],
    next_action: 'PROCEED',
   variation_structure: previous.variation_structure,
    sizes: previous.sizes,
    colors: previous.colors,
     matrix_assignments: previous.matrix_assignments || null,
    items: previous.items
  }
}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}

const AMAZON_TIP = 'Use clear Amazon-friendly values such as Red, Green, Yellow, XL, Medium, Light, Dark.';

function normalizeVariationValue(value) {
  const trimmed = String(value ?? '').trim();
  const lower = trimmed.toLowerCase();

  if (lower === 'extra large' || lower === 'extra-large') {
    return { trimmed, has_formatting_issue: true, suggestion: 'XL',
      question_to_user: 'Your size value "' + trimmed + '" is not in Amazon\'s standard format. Amazon uses "XL" for extra large. Should we use "XL"?',
      issue_code: 'NON_STANDARD_SIZE' };
  }
  if (lower === 'extra small' || lower === 'extra-small') {
    return { trimmed, has_formatting_issue: true, suggestion: 'XS',
      question_to_user: 'Your size value "' + trimmed + '" is not in Amazon\'s standard format. Amazon uses "XS" for extra small. Should we use "XS"?',
      issue_code: 'NON_STANDARD_SIZE' };
  }
  if (lower === 'double extra large' || lower === 'xxl') {
    return { trimmed, has_formatting_issue: true, suggestion: 'XXL',
      question_to_user: 'Your size value "' + trimmed + '" is not in Amazon\'s standard format. Amazon uses "XXL" for double extra large. Should we use "XXL"?',
      issue_code: 'NON_STANDARD_SIZE' };
  }
  if (trimmed.includes('-')) {
    const suggestion = trimmed.replace(/-/g, ' ');
    return { trimmed, has_formatting_issue: true, suggestion: suggestion,
      question_to_user: 'Your variation value "' + trimmed + '" contains a hyphen. Amazon typically uses spaces instead (e.g., "' + suggestion + '"). Should we use "' + suggestion + '"?',
      issue_code: 'HYPHEN_IN_VALUE' };
  }
  if (trimmed.includes('_')) {
    const suggestion = trimmed.replace(/_/g, ' ');
    return { trimmed, has_formatting_issue: true, suggestion: suggestion,
      question_to_user: 'Your variation value "' + trimmed + '" contains an underscore. Amazon typically uses spaces instead (e.g., "' + suggestion + '"). Should we use "' + suggestion + '"?',
      issue_code: 'UNDERSCORE_IN_VALUE' };
  }
  return { trimmed, has_formatting_issue: false, suggestion: null,
    question_to_user: null, issue_code: null };
}

const items = previous.items;
const issues = [];
const seenValues = {};

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  if (!item.variation_value || String(item.variation_value).trim() === '') {
    issues.push({
      issue_code: 'MISSING_VARIATION_VALUE',
      severity: 'fixable',
      asin: item.asin,
      sku: item.sku,
      field: 'variation_value',
      message: item.sku + ' is missing its variation value.',
      question_to_user: 'Please enter the color or size for ' + item.sku + '.',
      example_answer: 'Red',
      can_user_fix: true,
      can_user_override: false
    });
    continue;
  }

  const norm = normalizeVariationValue(item.variation_value);

  if (norm.has_formatting_issue) {
    issues.push({
      issue_code: norm.issue_code,
      severity: 'fixable',
      asin: item.asin,
      sku: item.sku,
      field: 'variation_value',
      current_value: norm.trimmed,
      suggested_value: norm.suggestion,
      message: 'Formatting issue detected on ' + item.sku + '.',
      question_to_user: norm.question_to_user,
      example_answer: norm.suggestion,
      can_user_fix: true,
      can_user_override: false
    });
    continue;
  }

  const key = norm.trimmed.toLowerCase();
  if (seenValues[key]) {
    issues.push({
      issue_code: 'DUPLICATE_VARIATION_VALUE',
      severity: 'hard_block',
      asin: item.asin,
      sku: item.sku,
      field: 'variation_value',
      duplicate_of_sku: seenValues[key],
      message: item.sku + ' has the same variation value as ' + seenValues[key] + ' (' + norm.trimmed + ').',
      question_to_user: null,
      can_user_fix: false,
      can_user_override: false
    });
  } else {
    seenValues[key] = item.sku;
  }
}

const hasHardBlock = issues.some(function(iss) {
  return iss.severity === 'hard_block';
});

if (hasHardBlock) {
  return [{
    json: {
      request_id: previous.request_id,
      decision: 'BLOCKED',
      variation_theme: previous.variation_structure,
      tip: AMAZON_TIP,
      issue_summary: 'One or more hard blocks prevent this merge.',
      issues: issues,
      next_action: 'CANCEL_OR_FIX_DATA'
    }
  }];
}

if (issues.length > 0) {
  return [{
    json: {
      request_id: previous.request_id,
      decision: 'NEEDS_INPUT',
      variation_theme: previous.variation_structure,
      tip: AMAZON_TIP,
      issue_summary: issues.length + ' issue(s) need your input before continuing.',
      issues: issues,
      next_action: 'USER_CLARIFICATION_REQUIRED'
    }
  }];
}

return [{
  json: {
    request_id: previous.request_id,
    decision: 'CAN_CONTINUE_TO_DRY_RUN',
    variation_theme: previous.variation_structure,
    tip: AMAZON_TIP,
    issue_summary: 'All variation values are valid.',
    issues: [],
    validated_items: items,
    next_action: 'PROCEED'
  }
}];

const prev = $input.first().json;
return [{ json: {
  _original_payload: prev,
  request_id: prev.request_id,
  decision: prev.decision,
  reason_code: prev.reason_code || prev.issues?.[0]?.issue_code || null,
  issue_summary: prev.issue_summary || null,
  hard_blocks_json: JSON.stringify(
    (prev.issues || []).filter(i => i.severity === 'hard_block')
  ),
  raw_result_json: JSON.stringify(prev),
  issues_json: JSON.stringify(prev.issues || []),
  next_action: prev.next_action || null
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}

const sizes = previous.sizes || (previous.data ? previous.data.sizes : null);
const colors = previous.colors || (previous.data ? previous.data.colors : null);

if (!Array.isArray(sizes) || sizes.length === 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'MISSING_SIZES_ARRAY',
    message: 'sizes array is missing or empty. Required for double_theme.',
    variation_structure: previous.variation_structure
  }}];
}

if (!Array.isArray(colors) || colors.length === 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'MISSING_COLORS_ARRAY',
    message: 'colors array is missing or empty. Required for double_theme.',
    variation_structure: previous.variation_structure
  }}];
}

const matrix = [];
let cellIndex = 0;

for (let r = 0; r < sizes.length; r++) {
  const row = [];
  for (let c = 0; c < colors.length; c++) {
    cellIndex++;
    row.push({
      cell_id: 'CELL-' + cellIndex,
      size: sizes[r],
      color: colors[c],
      sku: null,
      asin: null,
      status: 'empty'
    });
  }
  matrix.push(row);
}

const totalCells = sizes.length * colors.length;

return [{ json: {
  request_id: previous.request_id,
  decision: 'MATRIX_READY',
  variation_structure: previous.variation_structure,
  sizes: sizes,
  colors: colors,
  matrix: matrix,
  matrix_summary: {
    total_cells: totalCells,
    filled_cells: 0,
    empty_cells: totalCells

  },
     matrix_assignments: previous.matrix_assignments || null, 
  items: previous.items
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}

const matrix = previous.matrix;
const assignments = previous.matrix_assignments ||
  (previous.data ? previous.data.matrix_assignments : null);

// If no assignments sent yet, return the empty matrix as-is
if (!Array.isArray(assignments) || assignments.length === 0) {
  return [{ json: previous }];
}

// Check for duplicate SKUs across all assignments
const skuCount = {};
for (let i = 0; i < assignments.length; i++) {
  const sku = assignments[i].sku;
  if (!sku) continue;
  skuCount[sku] = (skuCount[sku] || 0) + 1;
}
const duplicateSkus = Object.keys(skuCount).filter(function(s) {
  return skuCount[s] > 1;
});
if (duplicateSkus.length > 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'DUPLICATE_MATRIX_ASSIGNMENT',
    message: 'The following SKU(s) have been assigned to more than one cell: ' + duplicateSkus.join(', ') + '. Each SKU can only appear once in the matrix.',
    duplicate_skus: duplicateSkus,
    variation_structure: previous.variation_structure,
    matrix: previous.matrix,
    items: previous.items
  }}];
}

// Build lookup: cell_id → assignment
const assignmentMap = {};
for (let i = 0; i < assignments.length; i++) {
  assignmentMap[assignments[i].cell_id] = assignments[i];
}

// Merge assignments into the matrix
const updatedMatrix = [];
let filledCount = 0;

for (let r = 0; r < matrix.length; r++) {
  const updatedRow = [];
  for (let c = 0; c < matrix[r].length; c++) {
    const cell = matrix[r][c];
    const match = assignmentMap[cell.cell_id];
    if (match) {
      updatedRow.push({
        cell_id: cell.cell_id,
        size: cell.size,
        color: cell.color,
        sku: match.sku,
        asin: match.asin || null,
        status: 'filled'
      });
      filledCount++;
    } else {
      updatedRow.push(cell);
    }
  }
  updatedMatrix.push(updatedRow);
}

const totalCells = previous.matrix_summary.total_cells;
const emptyCount = totalCells - filledCount;

// All done — Matrix Validator handles empty cell checks
return [{ json: {
  request_id: previous.request_id,
  decision: 'ASSIGNMENT_COMPLETE',
  variation_structure: previous.variation_structure,
  sizes: previous.sizes,
  colors: previous.colors,
  matrix: updatedMatrix,
  matrix_assignments: previous.matrix_assignments || null,
  matrix_summary: {
    total_cells: totalCells,
    filled_cells: filledCount,
    empty_cells: emptyCount
  },
  items: previous.items
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}

// Pass NEEDS_CONFIRMATION straight through — seller hasn't confirmed yet
if (previous.decision === 'NEEDS_CONFIRMATION') {
  return [{ json: previous }];
}

const matrix = previous.matrix;
const items = previous.items;
const issues = [];

// Build a set of parent SKUs from the items array
const parentSkus = {};
for (let i = 0; i < items.length; i++) {
  if (items[i].parentage === 'parent') {
    parentSkus[items[i].sku] = true;
  }
}

// Flatten matrix into a single array of cells for easier iteration
const allCells = [];
for (let r = 0; r < matrix.length; r++) {
  for (let c = 0; c < matrix[r].length; c++) {
    allCells.push(matrix[r][c]);
  }
}

// Check 1 — Duplicate size+color combination
const comboSeen = {};
for (let i = 0; i < allCells.length; i++) {
  const cell = allCells[i];
  if (cell.status !== 'filled') continue;
  const comboKey = cell.size + '|' + cell.color;
  if (comboSeen[comboKey]) {
    issues.push({
      issue_code: 'DUPLICATE_MATRIX_COMBINATION',
      severity: 'hard_block',
      cell_id: cell.cell_id,
      size: cell.size,
      color: cell.color,
      sku: cell.sku,
      message: 'Two SKUs share the same variation combination ' + cell.size + '/' + cell.color + '. Each size+color combination must be unique.',
      question_to_user: null,
      can_user_fix: false,
      can_user_override: false
    });
  }
  comboSeen[comboKey] = true;
}

// Check 2 — Nested parent structure
for (let i = 0; i < allCells.length; i++) {
  const cell = allCells[i];
  if (cell.status !== 'filled') continue;
  if (parentSkus[cell.sku]) {
    issues.push({
      issue_code: 'NESTED_PARENT_STRUCTURE',
      severity: 'hard_block',
      cell_id: cell.cell_id,
      size: cell.size,
      color: cell.color,
      sku: cell.sku,
      message: cell.sku + ' is already a parent SKU and cannot be assigned as a child. Amazon only supports one parent with direct children — never a parent of a parent.',
      question_to_user: null,
      can_user_fix: false,
      can_user_override: false
    });
  }
}

